<label><span style="display:flex;gap:5px;align-items:center"><input id="showGhostOutlineInput" type="checkbox" onchange="toggle_showGhostOutline(this.checked)"> Show original active-site outline</span></label>
<span style="font-size:10px;color:#666;line-height:1.4">Hover any shape for its name; click for a short explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var EF = '#e9f2cd', ES = '#7aa42a';          // enzyme fill / olive outline
  var SF = '#c8b5e3', SS = '#584080';          // substrate lavender / dark purple
  var PINK = '#ddab99', TAN = '#d9ab86', PS = '#8d6a58';
  var INK = '#111111';

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(100, 0, 440, 450);
  var root = draw.group();

  var state = { induced: false, p: 0, ghost: false };
  var animId = 0;

  function clamp(t) { return t < 0 ? 0 : (t > 1 ? 1 : t); }
  function ease(t) { t = clamp(t); return t * t * (3 - 2 * t); }
  function f(n) { return Math.round(n * 10) / 10; }
  function lerp(a, b, t) { return a + (b - a) * t; }

  var TOPY = 249;

  var LOCK = { xL: 298, wL: 10, bL: 281, xR: 336, wR: 11, bR: 281, ridgeY: 251, rise: 0 };
  var IND_OPEN = { xL: 291, wL: 17, bL: 260, xR: 345, wR: 19, bR: 262, ridgeY: 254, rise: 0 };
  var IND_SHUT = { xL: 298, wL: 10, bL: 281, xR: 336, wR: 11, bR: 281, ridgeY: 250, rise: 8 };

  function cleftParams(p) {
    if (!state.induced) return LOCK;
    var t = ease((p - 0.15) / 0.8);
    var o = {};
    for (var k in IND_OPEN) o[k] = lerp(IND_OPEN[k], IND_SHUT[k], t);
    return o;
  }

  function enzymePathStr(c) {
    var rimY = TOPY - c.rise;
    var lx = c.xL - c.wL, rx = c.xR + c.wR;
    var cL = Math.min(9, (c.bL - TOPY) * 0.5);
