<label>Binding progress: <output id="bindingProgressVal">0</output>
  <input id="bindingProgressInput" type="range" min="0" max="1" step="0.01" value="0" oninput="document.getElementById('bindingProgressVal').value=this.value;update_bindingProgress(+this.value)">
</label>
<button onclick="trigger_playBinding()">▶ Play substrate docking</button>
<label><span style="display:flex;gap:5px;align-items:center"><input id="showGhostOutlineInput" type="checkbox" onchange="toggle_showGhostOutline(this.checked)"> Show original active-site outline</span></label>
<span style="font-size:10px;color:#666;line-height:1.4">Hover any shape for its name; click for a short explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var EF = '#e9f2cd', ES = '#7aa42a';          // enzyme fill / olive outline
  var SF = '#c8b5e3', SS = '#584080';          // substrate lavender / dark purple
  var PINK = '#ddab99', TAN = '#d9ab86', PS = '#8d6a58';
  var INK = '#111111';

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(100, 0, 440, 450);
  var root = draw.group();

  var state = { induced: false, p: 0, ghost: false };
  var animId = 0;

  function clamp(t) { return t < 0 ? 0 : (t > 1 ? 1 : t); }
  function ease(t) { t = clamp(t); return t * t * (3 - 2 * t); }
  function f(n) { return Math.round(n * 10) / 10; }
  function lerp(a, b, t) { return a + (b - a) * t; }

  var TOPY = 249;

  var LOCK = { xL: 298, wL: 10, bL: 281, xR: 336, wR: 11, bR: 281, ridgeY: 251, rise: 0 };
  var IND_OPEN = { xL: 291, wL: 17, bL: 260, xR: 345, wR: 19, bR: 262, ridgeY: 254, rise: 0 };
  var IND_SHUT = { xL: 298, wL: 10, bL: 281, xR: 336, wR: 11, bR: 281, ridgeY: 250, rise: 8 };

  function cleftParams(p) {
    if (!state.induced) return LOCK;
    var t = ease((p - 0.15) / 0.8);
    var o = {};
    for (var k in IND_OPEN) o[k] = lerp(IND_OPEN[k], IND_SHUT[k], t);
    return o;
  }

  function enzymePathStr(c) {
    var rimY = TOPY - c.rise;
    var lx = c.xL - c.wL, rx = c.xR + c.wR;
    var cL = Math.min(9, (c.bL - TOPY) * 0.5);
    var xM = ((c.xL + c.wL) + (c.xR - c.wR)) / 2;
    var s = [];
    s.push('M 152 344');
    s.push('C 148 298 162 268 198 256');
    s.push('C 224 247 248 245 ' + f(lx) + ' ' + f(rimY));
    s.push('L ' + f(c.xL - c.wL * 0.92) + ' ' + f(c.bL - cL));
    s.push('Q ' + f(c.xL - c.wL * 0.92) + ' ' + f(c.bL) + ' ' + f(c.xL - c.wL * 0.35) + ' ' + f(c.bL));
    s.push('L ' + f(c.xL + c.wL * 0.35) + ' ' + f(c.bL));
    s.push('Q ' + f(c.xL + c.wL * 0.92) + ' ' + f(c.bL) + ' ' + f(c.xL + c.wL * 0.92) + ' ' + f(c.bL - cL));
    s.push('L ' + f(xM) + ' ' + f(c.ridgeY));
    s.push('L ' + f(c.xR) + ' ' + f(c.bR));
    s.push('L ' + f(rx) + ' ' + f(rimY));
    s.push('C ' + f(rx + 26) + ' 246 412 247 444 258');
    s.push('C 480 272 492 310 488 344');
    s.push('Q 488 362 470 362');
    s.push('L 170 362');
    s.push('Q 152 362 152 344 Z');
    return s.join(' ');
  }

  function inter(el, tip, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function () { showPopup(title, body); });
  }

  function txt(g, x, y, s, size, color, anchor) {
    var t = g.text(s).font({ family: 'sans-serif', size: size, anchor: anchor || 'middle' })
      .fill(color || INK).attr({ x: x, y: y, 'dominant-baseline': 'alphabetic' });
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    return t;
  }

  function arrow(g, x1, y1, x2, y2, op) {
    var ang = Math.atan2(y2 - y1, x2 - x1);
    var hl = 15, hw = 6.5;
    var bx = x2 - hl * Math.cos(ang), by = y2 - hl * Math.sin(ang);
    var px = -Math.sin(ang), py = Math.cos(ang);
    var gg = g.group().opacity(op);
    gg.line(x1, y1, bx, by).stroke({ color: INK, width: 3, linecap: 'round' });
    gg.polygon([[x2, y2], [bx + hw * px, by + hw * py], [bx - hw * px, by - hw * py]]).fill(INK);
    return gg;
  }

  function substrateA(g) {
    var gp = g.group();
    gp.path('M 289 234 L 307 234 L 307 272 L 289 272 Z').fill(SF).stroke({ color: SS, width: 3, linejoin: 'round' });
    var tip = gp.path('M 289 262 L 289 272 Q 289 282 298 282 Q 307 282 307 272 L 307 262 Z')
      .fill(PINK).stroke({ color: SS, width: 2.5, linejoin: 'round' });
    gp.path('M 320 145 L 286 145 Q 264 145 264 170 L 264 228 Q 264 251 288 251 L 320 251 Z')
      .fill(SF).stroke({ color: SS, width: 3.5, linejoin: 'round' });
    inter(gp, 'Substrate 1 — the molecule the enzyme acts on',
      'Substrate',
      'Substrates are the reactant molecules an enzyme binds. Only a molecule whose shape and chemistry are complementary to the active site can dock there — that is the origin of enzyme specificity.');
    inter(tip, 'Contact patch — shape + chemistry must match the pocket',
      'Complementary contact patch',
      'The coloured tip is the part of the substrate that actually touches the active site. Its shape and the weak chemical interactions it forms with the matching patch inside the cleft decide whether binding happens at all.');
    return gp;
  }

  function substrateB(g) {
    var gp = g.group();
    gp.path('M 326 234 L 346 234 L 342 268 L 330 268 Z').fill(SF).stroke({ color: SS, width: 3, linejoin: 'round' });
    var tip = gp.path('M 330 268 L 342 268 L 337.5 280 Q 336 283 334.5 280 Z')
      .fill(TAN).stroke({ color: SS, width: 2.5, linejoin: 'round' });
    gp.path('M 320 140 C 352 131 380 152 380 184 C 380 214 358 251 332 251 L 320 251 Z')
      .fill(SF).stroke({ color: SS, width: 3.5, linejoin: 'round' });
    inter(gp, 'Substrate 2 — binds alongside the first',
      'Substrate',
      'Many enzymes bring two substrates together. Each has its own complementary peg, so the pair can only be joined when both sit correctly in the active site.');
    inter(tip, 'Contact patch — tapered tip fits the V-shaped pocket',
      'Complementary contact patch',
      'This tapered tip fits the V-shaped half of the cleft. Note how it differs from the other substrate\'s rounded peg: the active site reads both shapes, so a wrong molecule simply cannot seat.');
    return gp;
  }

  function render() {
    root.clear();
    var p = state.p;
    var c = cleftParams(p);

    // --- enzyme body -------------------------------------------------------
    var body = root.path(enzymePathStr(c)).fill(EF).stroke({ color: ES, width: 4.5, linejoin: 'round' });
    inter(body, 'Enzyme — protein catalyst',
      'Enzyme',
      'The enzyme is a folded protein whose surface carries a small pocket, the active site. The bulk of the protein exists mainly to hold that pocket in exactly the right shape.');

    // --- contact patches inside the cleft ---------------------------------
    var hl = Math.min(6, (c.bL - TOPY) * 0.45);
    var lp = root.ellipse(c.wL * 1.55, hl * 2).center(c.xL, c.bL - hl * 0.9)
      .fill(PINK).stroke({ color: PS, width: 1.5 });
    var hr = Math.min(14, (c.bR - TOPY) * 0.7);
    var rp = root.polygon([[c.xR - c.wR * 0.55, c.bR - hr], [c.xR + c.wR * 0.55, c.bR - hr], [c.xR, c.bR - 1]])
      .fill(TAN).stroke({ color: PS, width: 1.5, linejoin: 'round' });
    var patchTip = 'Contact patches inside the active site — complementary to the substrate tips';
    inter(lp, patchTip, 'Active-site contact patch', 'These coloured regions are the amino-acid side chains that grip the substrate. Their arrangement mirrors the substrate tips, so a non-matching molecule makes no contacts and drifts away.');
    inter(rp, patchTip, 'Active-site contact patch', 'These coloured regions are the amino-acid side chains that grip the substrate. Their arrangement mirrors the substrate tips, so a non-matching molecule makes no contacts and drifts away.');

    // --- ghost of the unbound contour -------------------------------------
    if (state.ghost) {
      var g0 = root.path(enzymePathStr(cleftParams(0))).fill('none')
        .stroke({ color: '#8a8a8a', width: 2.4, linejoin: 'round' }).attr('stroke-dasharray', '9,6');
      inter(g0, state.induced ? 'Original (unbound) contour — the cleft has moved' : 'Original (unbound) contour — identical to the bound one',
        'Original active-site outline',
        state.induced
          ? 'The dashed line is the free enzyme\'s surface. In induced fit the solid outline pulls away from it: the enzyme changes shape as the substrate arrives.'
          : 'The dashed line is the free enzyme\'s surface. In the lock-and-key model it sits exactly on the bound outline — the pocket is rigid and pre-formed.');
    }

    // --- invisible hit target over the cleft ------------------------------
    var hit = root.rect(c.wL * 2 + c.wR * 2 + 34, 44).move(c.xL - c.wL - 10, TOPY - 10)
      .fill({ color: '#ffffff', opacity: 0.01 });
    inter(hit, 'Active site — the cleft where catalysis happens',
      'Active site',
      'The active site is a small cleft, only a handful of amino acids wide. Its shape and chemistry determine which substrates bind; in induced fit that shape is finalised only once the substrate is in place.');

    // --- substrates --------------------------------------------------------
    var hx = ease(p / 0.45);
    var vy = ease((p - 0.3) / 0.7);
    var dx = 48 * (1 - hx), dy = 60 * (1 - vy);

    var gA = root.group(); substrateA(gA); gA.transform({ translate: [-dx, -dy] });
    var gB = root.group(); substrateB(gB); gB.transform({ translate: [dx, -dy] });

    // --- seam between the two bound substrates ----------------------------
    var seamOp = clamp((p - 0.4) / 0.25);
    if (seamOp > 0.01) {
      root.line(320, 143 - dy, 320, 253 - dy).stroke({ color: INK, width: 5, linecap: 'round' }).opacity(seamOp);
    }

    // --- approach arrows ---------------------------------------------------
    var aOp = clamp(1 - p / 0.5);
    if (aOp > 0.02) {
      arrow(root, 296, 188, 310, 238, aOp);
      arrow(root, 344, 188, 330, 238, aOp);
    }

    // --- labels ------------------------------------------------------------
    var lbl = root.group();
    var subOp = clamp(1 - p / 0.4);
    if (subOp > 0.02) {
      var gs = lbl.group().opacity(subOp);
      txt(gs, 320, 32, 'Substrates', 17);
      gs.line(290, 38, 252, 90).stroke({ color: INK, width: 1.6 });
      gs.line(350, 38, 390, 86).stroke({ color: INK, width: 1.6 });
    }

    var modOp = clamp(1 - p / 0.32);
    if (modOp > 0.02) {
      var gm = lbl.group().opacity(modOp);
      var lines = state.induced ? ['Active', 'site', 'changes', 'to fit'] : ['Active', 'site is', 'proper', 'shape'];
      for (var i = 0; i < lines.length; i++) txt(gm, 320, 104 + i * 21, lines[i], 16);
    }

    var cOp = clamp((p - 0.62) / 0.3);
    if (cOp > 0.02) {
      var gc = lbl.group().opacity(cOp);
      var cl = ['Substrate', 'complex', 'formed'];
      for (var j = 0; j < cl.length; j++) txt(gc, 320, 52 + j * 21, cl[j], 16);
    }

    if (state.induced && p > 0.35) {
      var gcb = lbl.group().opacity(clamp((p - 0.35) / 0.25));
      gcb.line(236, 212, 286, 243).stroke({ color: '#666', width: 1.3 }).attr('stroke-dasharray', '4,3');
      txt(gcb, 196, 208, 'active site reshapes', 12, '#555');
    }

    txt(lbl, 320, 392, 'Enzyme', 17);
    txt(lbl, 320, 431, state.induced ? '(b) Induced fit model' : '(a) Lock-and-key model', 17);
  }

  // ---- control handlers ---------------------------------------------------
  window.toggle_modelToggle = function (on) {
    state.induced = !!on;
    render();
  };
  window.update_bindingProgress = function (v) {
    state.p = v;
    render();
  };
  window.toggle_showGhostOutline = function (on) {
    state.ghost = !!on;
    render();
  };
  window.trigger_playBinding = function () {
    if (animId) cancelAnimationFrame(animId);
    var t0 = null, dur = 2200;
    var slider = document.getElementById('bindingProgressInput');
    var out = document.getElementById('bindingProgressVal');
    function frame(ts) {
      if (t0 === null) t0 = ts;
      var k = clamp((ts - t0) / dur);
      state.p = k;
      slider.value = k; out.value = Math.round(k * 100) / 100;
      render();
      if (k < 1) { animId = requestAnimationFrame(frame); } else { animId = 0; }
    }
    state.p = 0; slider.value = 0; out.value = 0; render();
    animId = requestAnimationFrame(frame);
  };

  // ---- demo steps ---------------------------------------------------------
  var steps = [
    { title: 'Free enzyme and substrates',
      narration: 'A green enzyme sits below two purple substrate molecules. Hover any part to name it: enzyme body, active site cleft, and the small colored contact patches that must match.',
      state: { modelToggle: 'Lock-and-key', bindingProgress: 0, showGhostOutline: false } },
    { title: 'Lock-and-key: the pocket is already right',
      narration: 'Drag binding progress forward. The substrates descend and slot in, but trace the cleft outline — it never moves. The active site is a rigid, pre-formed shape.',
      state: { modelToggle: 'Lock-and-key', bindingProgress: 1, showGhostOutline: true } },
    { title: 'Switch to induced fit, unbound',
      narration: 'Now the same enzyme is drawn with a shallower, more open cleft — it does not yet match the substrates. Under lock-and-key logic, nothing should bind here.',
      state: { modelToggle: 'Induced fit', bindingProgress: 0, showGhostOutline: false } },
    { title: 'Induced fit: the pocket closes in',
      narration: 'Sweep the slider again. As the substrates approach, the enzyme\'s surface deforms and wraps around them — the dashed ghost shows where the cleft used to be.',
      state: { modelToggle: 'Induced fit', bindingProgress: 1, showGhostOutline: true } },
    { title: 'Compare the two complexes',
      narration: 'Play the docking animation in each mode back to back. Both end in a tight substrate complex — the difference is whether the enzyme had to move to get there.',
      state: { modelToggle: 'Induced fit', bindingProgress: 1, showGhostOutline: false } }
  ];
  var cur = 0;

  function applyStep(i) {
    if (animId) { cancelAnimationFrame(animId); animId = 0; }
    cur = (i + steps.length) % steps.length;
    var s = steps[cur];
    var ind = (s.state.modelToggle === 'Induced fit');
    document.getElementById('modelToggleInput').checked = ind;
    state.induced = ind;
    var p = s.state.bindingProgress;
    document.getElementById('bindingProgressInput').value = p;
    document.getElementById('bindingProgressVal').value = p;
    state.p = p;
    document.getElementById('showGhostOutlineInput').checked = !!s.state.showGhostOutline;
    state.ghost = !!s.state.showGhostOutline;
    document.getElementById('demoNarration').innerHTML =
      '<b>' + s.title + '</b><br>' + s.narration;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

