// @FIGURE_CODE_BEGIN
(function () {
  var EF = '#e9f2cd', ES = '#7aa42a';          // enzyme fill / olive outline
  var SF = '#c5b3e0', SS = '#5a4280';          // substrate lavender / dark purple
  var PINK = '#ddab99', TAN = '#d8a984', PS = '#8d6a58';
  var INK = '#111111';

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(99, 0, 420, 480);
  var root = draw.group();

  var state = { induced: false, p: 0, ghost: false };
  var animId = 0;

  function clamp(t) { return t < 0 ? 0 : (t > 1 ? 1 : t); }
  function ease(t) { t = clamp(t); return t * t * (3 - 2 * t); }
  function f(n) { return Math.round(n * 10) / 10; }
  function lerp(a, b, t) { return a + (b - a) * t; }
  function pt(p) { return f(p[0]) + ' ' + f(p[1]); }

  var RIMY = 262, CX = 309;

  // --- cleft control points (lock-and-key reference geometry) --------------
  //  0 rim-L · 1 wall · 2,3 rounded pocket floor · 4 wall · 5 central spike
  //  6 wall · 7 V floor · 8 wall · 9 rim-R
  var CLEFT = [
    [268, 262], [274, 288], [286, 303], [298, 303], [306, 288],
    [309, 258], [313, 288], [330, 305], [347, 284], [353, 262]
  ];

  function xf(wf, df, peakDy, rimDy) {
    return CLEFT.map(function (p, i) {
      var x = CX + (p[0] - CX) * wf;
      var y = RIMY + (p[1] - RIMY) * df;
      if (i === 5) y += peakDy;
      if (i === 0 || i === 9) y = RIMY + rimDy;
      return [x, y];
    });
  }
  var OPEN = xf(1.32, 0.40, 9, 0);    // induced fit, unbound: broad & shallow
  var SHUT = xf(0.96, 1.05, -2, -8);  // induced fit, bound: pinched & curled up

  function cleftParams(p) {
    if (!state.induced) return CLEFT;
    var t = ease((p - 0.12) / 0.82);
    var out = [];
    for (var i = 0; i < OPEN.length; i++) {
      out.push([lerp(OPEN[i][0], SHUT[i][0], t), lerp(OPEN[i][1], SHUT[i][1], t)]);
    }
    return out;
  }

  function enzymePathStr(c) {
    var s = [];
    s.push('M 150 364');
    s.push('C 146 322 160 292 194 274');
    s.push('C 218 262 244 256 ' + pt(c[0]));
    s.push('L ' + pt(c[1]));
    s.push('Q ' + f(c[1][0]) + ' ' + f(c[2][1]) + ' ' + pt(c[2]));
    s.push('L ' + pt(c[3]));
    s.push('Q ' + f(c[4][0]) + ' ' + f(c[3][1]) + ' ' + pt(c[4]));
    s.push('L ' + pt(c[5]));
    s.push('L ' + pt(c[6]));
    s.push('L ' + pt(c[7]));
    s.push('L ' + pt(c[8]));
    s.push('L ' + pt(c[9]));
    s.push('C ' + f(c[9][0] + 28) + ' 256 400 256 428 272');
    s.push('C 460 290 472 322 468 364');
    s.push('Q 468 384 448 384');
    s.push('L 170 384');
    s.push('Q 150 384 150 364 Z');
    return s.join(' ');
  }

  function inter(el, tip, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip, e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function () { showPopup(title, body); });
  }

  function txt(g, x, y, s, size, color, anchor) {
    var t = g.text(s).font({ family: 'sans-serif', size: size, anchor: anchor || 'middle' })
      .fill(color || INK).attr({ x: x, y: y, 'dominant-baseline': 'alphabetic' });
    t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.5, 'stroke-linejoin': 'round' });
    return t;
  }

  function arrow(g, x1, y1, x2, y2, op) {
    var ang = Math.atan2(y2 - y1, x2 - x1);
    var hl = 17, hw = 7.5;
    var bx = x2 - hl * Math.cos(ang), by = y2 - hl * Math.sin(ang);
    var px = -Math.sin(ang), py = Math.cos(ang);
    var gg = g.group().opacity(op);
    gg.line(x1, y1, bx, by).stroke({ color: INK, width: 3.2, linecap: 'round' });
    gg.polygon([[x2, y2], [bx + hw * px, by + hw * py], [bx - hw * px, by - hw * py]]).fill(INK);
    return gg;
  }

  // --- substrates (drawn in their BOUND position, then translated) ---------
  function substrateA(g) {
    var gp = g.group();
    // rounded-box body with flat right (seam) edge
    gp.path('M 309 168 L 266 168 Q 244 168 244 190 L 244 234 Q 244 256 266 256 L 309 256 Z')
      .fill(SF).stroke({ color: SS, width: 3.6, linejoin: 'round' });
    // rectangular peg
    gp.path('M 283 248 L 301 248 L 301 292 L 283 292 Z')
      .fill(SF).stroke({ color: SS, width: 3, linejoin: 'round' });
    var tip = gp.path('M 283 284 L 301 284 L 301 293 Q 301 303 292 303 Q 283 303 283 293 Z')
      .fill(PINK).stroke({ color: SS, width: 2.6, linejoin: 'round' });
    inter(gp, 'Substrate 1 — the molecule the enzyme acts on',
      'Substrate',
      'Substrates are the reactant molecules an enzyme binds. Only a molecule whose shape and chemistry are complementary to the active site can dock there — that is the origin of enzyme specificity.');
    inter(tip, 'Contact patch — rounded peg matches the rounded pocket',
      'Complementary contact patch',
      'The coloured tip is the part of the substrate that actually touches the active site. Its shape and the weak chemical interactions it forms with the matching patch inside the cleft decide whether binding happens at all.');
    return gp;
  }

  function substrateB(g) {
    var gp = g.group();
    gp.path('M 309 164 C 350 151 382 175 384 209 C 386 240 358 256 332 256 L 309 256 Z')
      .fill(SF).stroke({ color: SS, width: 3.6, linejoin: 'round' });
    gp.path('M 321 248 L 339 248 L 337 288 L 323 288 Z')
      .fill(SF).stroke({ color: SS, width: 3, linejoin: 'round' });
    var tip = gp.path('M 323 286 L 337 286 L 331.5 301 Q 330 305 328.5 301 Z')
      .fill(TAN).stroke({ color: SS, width: 2.6, linejoin: 'round' });
    inter(gp, 'Substrate 2 — binds alongside the first',
      'Substrate',
      'Many enzymes bring two substrates together. Each has its own complementary peg, so the pair can only be joined when both are seated correctly in the active site.');
    inter(tip, 'Contact patch — tapered tip fits the V-shaped pocket',
      'Complementary contact patch',
      'This tapered tip fits the V-shaped half of the cleft. Note how it differs from the other substrate\'s rounded peg: the active site reads both shapes, so a wrong molecule simply cannot seat.');
    return gp;
  }

  var PATCH_POP = ['Active-site contact patch',
    'These coloured regions are the amino-acid side chains that grip the substrate. Their arrangement mirrors the substrate tips, so a non-matching molecule makes no contacts and drifts away.'];

  function render() {
    root.clear();
    var p = state.p;
    var c = cleftParams(p);

    // --- enzyme body -------------------------------------------------------
    var body = root.path(enzymePathStr(c)).fill(EF).stroke({ color: ES, width: 5, linejoin: 'round' });
    inter(body, 'Enzyme — protein catalyst',
      'Enzyme',
      'The enzyme is a folded protein whose surface carries a small pocket, the active site. The bulk of the protein exists mainly to hold that pocket in exactly the right shape.');

    // --- contact patches inside the cleft ---------------------------------
    var rimTop = Math.min(c[0][1], c[9][1]);
    var dL = c[2][1] - rimTop;
    var ryL = Math.max(2.5, Math.min(7, dL * 0.28));
    var lp = root.ellipse((c[3][0] - c[2][0]) + 16, ryL * 2)
      .center((c[2][0] + c[3][0]) / 2, c[2][1] - ryL * 0.85)
      .fill(PINK).stroke({ color: PS, width: 1.6 });
    var dR = c[7][1] - c[5][1];
    var hR = Math.max(4, Math.min(16, dR * 0.5));
    var rp = root.polygon([
      [c[7][0] - hR * 0.8, c[7][1] - hR],
      [c[7][0] + hR * 0.8, c[7][1] - hR],
      [c[7][0], c[7][1] - 1.5]
    ]).fill(TAN).stroke({ color: PS, width: 1.6, linejoin: 'round' });
    var ptip = 'Contact patches inside the active site — complementary to the substrate tips';
    inter(lp, ptip, PATCH_POP[0], PATCH_POP[1]);
    inter(rp, ptip, PATCH_POP[0], PATCH_POP[1]);

    // --- dashed ghost of the unbound contour ------------------------------
    if (state.ghost) {
      var g0 = root.path(enzymePathStr(cleftParams(0))).fill('none')
        .stroke({ color: '#7d7d7d', width: 2.6, linejoin: 'round' }).attr('stroke-dasharray', '10,6');
      inter(g0, state.induced ? 'Original (unbound) contour — the cleft has moved' : 'Original (unbound) contour — identical to the bound one',
        'Original active-site outline',
        state.induced
          ? 'The dashed line is the free enzyme\'s surface. In induced fit the solid outline pulls away from it: the enzyme changes shape as the substrate arrives.'
          : 'The dashed line is the free enzyme\'s surface. In the lock-and-key model it sits exactly on the bound outline — the pocket is rigid and pre-formed.');
    }

    // --- invisible hit target over the cleft ------------------------------
    var hitX = c[0][0] - 8, hitW = (c[9][0] - c[0][0]) + 16;
    var hitY = rimTop - 12, hitH = (Math.max(c[2][1], c[7][1]) - rimTop) + 20;
    var hit = root.rect(hitW, hitH).move(hitX, hitY).fill({ color: '#ffffff', opacity: 0.01 });
    inter(hit, 'Active site — the cleft where catalysis happens',
      'Active site',
      'The active site is a small cleft, only a handful of amino acids wide. Its shape and chemistry determine which substrates bind; in induced fit that shape is finalised only once the substrate is in place.');

    // --- substrates --------------------------------------------------------
    var hx = ease(p / 0.45);
    var vy = ease((p - 0.28) / 0.72);
    var dx = 62 * (1 - hx), dy = 70 * (1 - vy);

    var gA = root.group(); substrateA(gA); gA.transform({ translate: [-dx, -dy] });
    var gB = root.group(); substrateB(gB); gB.transform({ translate: [dx, -dy] });

    // --- black seam between the two bound substrates ----------------------
    var seamOp = clamp((p - 0.42) / 0.25);
    if (seamOp > 0.01) {
      root.line(CX, 162 - dy, CX, 266 - dy).stroke({ color: INK, width: 5.5, linecap: 'butt' }).opacity(seamOp);
    }

    // --- approach arrows ---------------------------------------------------
    var aOp = clamp(1 - p / 0.45);
    if (aOp > 0.02) {
      arrow(root, 290, 188, 302, 250, aOp);
      arrow(root, 336, 188, 322, 250, aOp);
    }

    // --- labels (drawn last, with halos) ----------------------------------
    var lbl = root.group();
    var subOp = clamp(1 - p / 0.4);
    if (subOp > 0.02) {
      var gs = lbl.group().opacity(subOp);
      gs.line(272, 44, 216, 92).stroke({ color: INK, width: 1.7 });
      gs.line(348, 44, 402, 90).stroke({ color: INK, width: 1.7 });
      txt(gs, CX, 36, 'Substrates', 18);
    }

    var modOp = clamp(1 - p / 0.34);
    if (modOp > 0.02) {
      var gm = lbl.group().opacity(modOp);
      var lines = state.induced ? ['Active', 'site', 'changes', 'to fit'] : ['Active', 'site is', 'proper', 'shape'];
      for (var i = 0; i < lines.length; i++) txt(gm, CX, 100 + i * 22, lines[i], 17);
    }

    var cOp = clamp((p - 0.62) / 0.3);
    if (cOp > 0.02) {
      var gc = lbl.group().opacity(cOp);
      var cl = ['Substrate', 'complex', 'formed'];
      for (var j = 0; j < cl.length; j++) txt(gc, CX, 52 + j * 22, cl[j], 17);
    }

    if (state.induced && p > 0.32) {
      var gcb = lbl.group().opacity(clamp((p - 0.32) / 0.25));
      gcb.line(232, 240, c[0][0] - 2, c[0][1] - 2).stroke({ color: '#666', width: 1.4 }).attr('stroke-dasharray', '4,3');
      gcb.circle(4).center(c[0][0] - 2, c[0][1] - 2).fill('#666');
      txt(gcb, 228, 238, 'active site reshapes', 12.5, '#555', 'end');
    }

    txt(lbl, CX, 418, 'Enzyme', 18);
    txt(lbl, CX, 458, state.induced ? '(b) Induced fit model' : '(a) Lock-and-key model', 18);
  }

  // ---- control handlers ---------------------------------------------------
  window.toggle_modelToggle = function (on) { state.induced = !!on; render(); };
  window.update_bindingProgress = function (v) { state.p = v; render(); };
  window.toggle_showGhostOutline = function (on) { state.ghost = !!on; render(); };
  window.trigger_playBinding = function () {
    if (animId) cancelAnimationFrame(animId);
    var t0 = null, dur = 2300;
    var slider = document.getElementById('bindingProgressInput');
    var out = document.getElementById('bindingProgressVal');
    function frame(ts) {
      if (t0 === null) t0 = ts;
      var k = clamp((ts - t0) / dur);
      state.p = k;
      slider.value = k; out.value = Math.round(k * 100) / 100;
      render();
      if (k < 1) { animId = requestAnimationFrame(frame); } else { animId = 0; }
    }
    state.p = 0; slider.value = 0; out.value = 0; render();
    animId = requestAnimationFrame(frame);
  };

  // ---- demo steps ---------------------------------------------------------
  var steps = [
    { title: 'Free enzyme and substrates',
      narration: 'A green enzyme sits below two purple substrate molecules. Hover any part to name it: enzyme body, the deep active-site cleft, and the small coloured contact patches whose shapes must match the substrate pegs.',
      state: { induced: false, p: 0, ghost: false } },
    { title: 'Lock-and-key: the pocket is already right',
      narration: 'Drag binding progress forward. The pegs descend and slot in, but trace the cleft outline — the dashed ghost never separates from it. The active site is a rigid, pre-formed shape.',
      state: { induced: false, p: 1, ghost: true } },
    { title: 'Switch to induced fit, unbound',
      narration: 'Now the free enzyme has a broad, shallow depression instead of a snug notch — it does not yet match the pegs. Under strict lock-and-key logic nothing should bind here.',
      state: { induced: true, p: 0, ghost: false } },
    { title: 'Induced fit: the pocket closes in',
      narration: 'Sweep the slider again. As the substrates approach, the olive surface deepens and curls inward to hug the pegs; the dashed ghost shows where the cleft used to be.',
      state: { induced: true, p: 1, ghost: true } },
    { title: 'Compare the two complexes',
      narration: 'Play the docking animation in each mode back to back. Both end in the same tight complex — the difference is whether the enzyme had to move to get there. Fit can be a consequence of binding, not a precondition.',
      state: { induced: true, p: 1, ghost: false } }
  ];
  var cur = 0;

  function applyStep(i) {
    if (animId) { cancelAnimationFrame(animId); animId = 0; }
    cur = (i + steps.length) % steps.length;
    var s = steps[cur];
    state.induced = s.state.induced;
    state.p = s.state.p;
    state.ghost = s.state.ghost;
    document.getElementById('modelToggleInput').checked = state.induced;
    document.getElementById('bindingProgressInput').value = state.p;
    document.getElementById('bindingProgressVal').value = state.p;
    document.getElementById('showGhostOutlineInput').checked = state.ghost;
    document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

